@Component("usageLimit-handler")
@ProcessingGroup("usageLimit-processing-group")
public class UsageLimitEventHandler {
	
	// core constructor
	UsageLimitEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateUsageLimitEvent
     */
    @EventHandler
    public void handle( CreateUsageLimitEvent event) {
        entityManager.persist(new UsageLimit(event.getUsageLimitId(), event.getName(), event.getAmount(), event.getCount(), event.getPricingPlan(), event.getScope(), event.getPeriod()));
    }

    /*
     * @param	event UpdateUsageLimitEvent
     */
    @EventHandler
    public UsageLimit handle( UpdateUsageLimitEvent event) {
    	entityManager.merge(new UsageLimit(event.getUsageLimitId(), event.getName(), event.getAmount(), event.getCount(), event.getPricingPlan(), event.getScope(), event.getPeriod()));
    }
    
    /*
     * @param	event DeleteUsageLimitEvent
     */
    @EventHandler
    public void on( DeleteUsageLimitEvent event) {
    	UsageLimit entity = new UsageLimit();
   
    	// ------------------------------------------
    	// apply the UsageLimitId
    	// ------------------------------------------
    	entity.setUsageLimitId( event.getUsageLimitId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final UsageLimitRepository usageLimitEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(UsageLimitEventHandler.class.getName());

}
